    "text_scrutiny": "澳門某跨境電商進出口公司在歐洲（歐元 EUR）、美國（美元 USD）與澳門（MOP）之間進行跨時區資金調撥。\n財務日誌顯示以下三筆跨國清算（統一折算為萬澳門元）：\n1. 收到歐洲客戶尾款：+45 萬元；\n2. 償還上月美元短期借款（減去負債）：- (-28) 萬元；\n3. 支付澳門倉庫租金與物流運費：+ (-35) 萬元；\n4. 突發匯率避險保證金扣減：- (+18) 萬元。\n公司新進實習生抱怨：『又是加負數、又是減負數，加減符號完全亂套了！減去負債到底是資產變多還是變少？』",
