    "domain": "變化與關係 (Change & Relationships)",
    "pisa_coords": "【內容範疇】變化與關係 (Change & Relationships) | 【情境】智慧出行與市政法規 | 【認知過程】多元代數式賦值求值與最優性價比決策 | 【前瞻要素】算法定價、參數敏感性",
    "text_scrutiny": "澳門特別行政區《輕型出租汽車客運規章》最新收費標準代數模型審查：\n總車費 C = 21 + 2 × ⌈max(0, s - 1600) / 220⌉ + 2 × ⌈t / 60⌉ + E。\n其中 s 為行駛里程（米），t 為停等時間（秒），E 為附加費（如路氹跨海或行李箱每件 3 元）。\n市民張小姐從關閘乘車到路氹威尼斯人，全程 11.2 公里（11200 米），遇到堵車累計等待 12 分鐘（720 秒），行李箱 2 件。司機收費 145 元。張小姐質疑司機多收了車費，打開手機電召 APP 發現估價為 138 元。請你作為交通事務局特邀仲裁員進行精確代數求值。",
    "misconception": "學生面對包含多個變量（里程 s、時間 t、行李數 E）與取整符號（向上取整）的複雜複合代數式時，容易單位換算混亂（把 11.2 公里忘記轉為米，12 分鐘忘記轉為秒），缺乏對不同參數敏感性的評估。",
    "cer": {
      "claim": "依據法定規章代數模型，精確應付車費為 144 澳門元；司機多收了 1 元應當退還，而叫車平台 138 元估算因低估堵車等待時間而失真。",
      "evidence": "代入求值：里程費 = 2 × ⌈(11200 - 1600)/220⌉ = 2 × 44 = 88 元；時間費 = 2 × (720/60) = 24 元；起步價 21 元；附加費 6元(行李) + 5元(跨海) = 11 元。總額 C = 21 + 88 + 24 + 11 = 144 元。司機收取 145 元多收 1 元。",
      "reasoning": "計程車計價模型是一個多變量分段階梯函數。計量器具具備嚴格的法定檢定標準。向上取整符號 ⌈ ⌉ 意味著不足 220 米或 60 秒均按滿額進位跳表。代數式的值精確映射了時間與空間資源的綜合消耗，任何四捨五入私自加價均屬違規運營。",
      "rebuttal": "反駁平台估價 138 元的質疑：平台估價通常只基於歷史空暢路況預測，無法提前預知突發堵車 12 分鐘（價值 24 元）。代數式計算的是『已發生的真實物理過程』，其權威性遠超統計預估值。"
    },
    "cps_challenge": "【計程車跳表計費器演算法】用 Python 語法實現 taxi_meter(distance_m, wait_seconds, luggage_count, is_cross_sea)，精確輸出費用明細清單。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：F(s, t) = 21 + 2 \\times \\left\\lceil \\frac{\\max(0, s - 1600)}{220} \\right\\rceil + 2 \\times \\left\\lfloor \\frac{t}{60} \\right\\rfloor$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
