      "evidence": "依據等量關係列方程：2x + 15 = x + 65。應用等式性質一：兩邊同減 x，得 x + 15 = 65；再同減 15，得 x = 50g。代入原方程驗證：左邊 = 2(50) + 15 = 115g，右邊 = 50 + 65 = 115g，左右嚴格相等。",
      "reasoning": "算術思維是『逆向溯源』，每一步都必須在大腦中完成反向邏輯推理；代數思維是『順向記錄』，只需將題目中的客觀平衡條件直接寫為符號等式。等式性質保障了在不破壞天平平衡的前提下，透過有限步機械化變形將未知數孤立。這標誌著思維方式從具象算術走向現代科學抽象代數。",
