    "title": "方程求解的標準消除演算法——移項、去括號、去分母的程序流程圖",
    "domain": "變化與關係 (Change & Relationships)",
    "pisa_coords": "【內容範疇】變化與關係 (Change & Relationships) | 【情境】算法設計與計算機科學 | 【認知過程】公理化解題流程的模組化分解與程序設計 | 【前瞻要素】LDW計算思維、流程圖設計",
    "text_scrutiny": "課本展示複雜一元一次方程：(2x - 1)/3 - (5x + 2)/6 = 1。\n某初一學生解題步驟如下：\n第 1 步：去分母得 2(2x - 1) - 5x + 2 = 1；（漏乘常數項 1，且減號後面未加括號）\n第 2 步：去括號得 4x - 2 - 5x + 2 = 1；\n第 3 步：移項得 4x - 5x = 1 + 2 - 2；\n第 4 步：化簡得 -x = 1 ➔ x = -1。\n作業批改顯示該題全錯！AI 編程社團提議：『人腦容易在去分母和移項時漏乘或忘記變號，我們能否為計算機設計一套永不犯錯的解方程標準化程序流程圖？』",
    "misconception": "學生解方程存在三大高頻死穴：① 去分母時整數項忘記乘以最小公倍數；② 分數線前的減號去分母後忘記將分子加括號；③ 移項跨過等號忘記變號（+ 變 -，- 變 +）。",
    "cer": {
      "claim": "原題正確唯一解為 x = -10；該學生在第 1 步犯了兩處致命錯誤：① 右側常數項 1 漏乘公倍數 6，② 分數線前負號作用於分子整體，未加括號導致第二項變號錯誤。",
      "evidence": "正確運算軌跡：兩邊乘以 6 得 2(2x - 1) - (5x + 2) = 6。展開得 4x - 2 - 5x - 2 = 6。合併同類項得 -x - 4 = 6，移項得 -x = 10，解得 x = -10。驗算左邊：[2(-10)-1]/3 - [5(-10)+2]/6 = (-21)/3 - (-48)/6 = -7 - (-8) = -7 + 8 = 1 = 右邊！",
      "reasoning": "解方程是一套有限步終止的嚴格演算法（Algorithm）。分數線兼具『除號』與『括號』雙重功能，去分母時分子必須補上括號保護整體符號；等式兩邊同乘以數必須對每一項無差別覆蓋（分配律）。跳步和輕視符號規則是引發程序崩潰的根源。",
      "rebuttal": "反駁『只是粗心看漏了』的藉口：數學中沒有粗心，只有概念不清晰。漏乘常數項本質是違背了等式基本性質二（只乘一部分破壞了平衡）；忘記變號是違背了減法去括號法則。標準化流程圖是根除錯誤的唯一武器。"
    },
