    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：ax + b = cx + d \\implies (a - c)x = d - b \\implies x = \\frac{d - b}{a - c} \\quad (a \\neq c)$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
    "exp_name": "方程求解的標準消除演算法 動態模擬實驗台",
    "exp_principle": "解方程是一套有限步終止的嚴格演算法（Algorithm）。分數線兼具『除號』與『括號』雙重功能，去分母時分子必須補上括號保護整體符號；等式兩邊同乘以數必須對每一項無差別覆蓋（分配律）。跳步和輕視符號規則是引發程序崩潰的根源。",
