    "domain": "變化與關係 (Change & Relationships)",
    "pisa_coords": "【內容範疇】變化與關係 (Change & Relationships) | 【情境】日常生活與通訊消費 | 【認知過程】分段函數成本方程構建與臨界點決策 | 【前瞻要素】PISA金融素養、臨界點方程",
    "text_scrutiny": "澳門電訊（CTM）5G 學生校園上網月費計劃對比審查：\n• 套餐 A（輕量型）：月租 68 澳門元，包含 10 GB 數據；超出後每 GB 收費 5 元；\n• 套餐 B（尊享型）：月租 118 澳門元，包含 30 GB 數據；超出後每 GB 收費 3 元。\n初一學生小明每月數據使用量大約在 15 GB 到 25 GB 之間波動。媽媽主張辦套餐 A，說『月租便宜 50 塊！』小明主張辦套餐 B，說『流量多更划算！』請你通過列方程求解兩套餐的費用平衡分界點（Break-even point），為小明家庭提供科學決策指南。",
    "misconception": "學生容易只盯著固定月租（68元 vs 118元）做選擇，或者只看超出單價（5元 vs 3元），缺乏將月用量 x 作為動態自變量，建立總成本方程並求出兩者交叉臨界點（交點）的系統性決策思維。",
