      "claim": "兩套餐的費用平衡臨界點恰好為每月使用 20 GB 數據流量；小明若月用量在 15-20 GB 應選套餐 A，若在 20-25 GB 應果斷選套餐 B。",
      "evidence": "在 10 < x ≤ 30 GB 範圍內：Cost_A = 68 + 5(x - 10) = 5x + 18；Cost_B = 118。令兩者相等列方程：5x + 18 = 118，解得 5x = 100 ➔ x = 20 GB。代入檢驗：當 x = 18 GB 時，Cost_A = 5(18)+18 = 108 元 < 118 元；當 x = 22 GB 時，Cost_A = 5(22)+18 = 128 元 > 118 元。",
