    "text_scrutiny": "港珠澳大橋（澳門段至西人工島）無人機海事巡檢指揮中心：\n上午 10:00，一架老款長航時巡檢無人機甲以 60 km/h 的勻速從澳門口岸停機坪起飛，沿大橋主線向東巡檢；\n由於突發海面油污警報，上午 10:20，指揮中心從同一地點緊急派遣高解析度激光雷達無人機乙以 100 km/h 的高速出發追趕，並在海面上空執行空中數據接力。\n指揮中心調度台屏幕提示：『預計乙機出發後行駛多少公里能追上甲機？接力點是否會超出西人工島（距離澳門口岸約 30 公里）的信號覆蓋範圍？』",
