    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：v_1 t = v_2 (t - t_0) + d_0 \\implies t = \\frac{d_0 - v_2 t_0}{v_1 - v_2} \\quad (v_1 > v_2)$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
