    "domain": "空間與形狀 (Space & Shape)",
    "pisa_coords": "【內容範疇】空間與形狀 (Space & Shape) | 【情境】軌道交通工程與光學儀器 | 【認知過程】幾何公理化命題演繹推導與因果論證 | 【前瞻要素】幾何演繹證明、跨學科光學",
    "text_scrutiny": "初一物理跨學科幾何探究課題《潛望鏡的秘密》與《輕軌雙軌道平行保障》：\n潛望鏡內部安裝有兩塊與筒壁成 45° 角的平面鏡 M1 和 M2（彼此相互平行）。光線射入潛望鏡，經過 M1 反射後射向 M2，再經 M2 反射射出進入觀察者眼中。\n物理學反射定律：入射角等於反射角（∠1 = ∠2，∠3 = ∠4）。\n軍事工程師宣稱：『無論潛望鏡怎麼做，只要兩塊鏡子平行，射出光線的方向絕對和入射光線方向保持 100% 嚴格平行！這是有嚴密幾何邏輯保證的！』請你給出完整的幾何三段論證明。",
    "misconception": "學生會背誦『同位角相等兩直線平行、內錯角相等兩直線平行』，但面對『性質（由平行推角相等）』與『判定（由角相等推平行）』時容易因果倒置，缺乏將物理反射規律與幾何平行公理建立嚴密演繹鏈條的邏輯功底。",
    "cer": {
      "claim": "在潛望鏡光學結構中，射出光線 CD 必然與入射光線 AB 保持嚴格平行（AB // CD）。",
      "evidence": "幾何推導：兩平面鏡平行（M1 // M2），其法線亦互相平行（N1 // N2）。光線在兩鏡面的入射角與反射角分別為 i1, r1 和 i2, r2。依據反射定律 i1 = r1, i2 = r2。由於法線平行，內錯角 r1 = i2。轉折角 ∠ABC = 180° - 2r1，∠BCD = 180° - 2i2。故 ∠ABC = ∠BCD（內錯角相等），即 AB // CD。",
      "reasoning": "平行的判定基於歐幾里得幾何平行公理。當且僅當一條截線所截得的內錯角相等或同旁內角互補時，兩直線必平行。潛望鏡利用法線平行的空間傳遞性，透過物理反射定律將角度等量代換，構建了不可動搖的同角因果鏈條。",
      "rebuttal": "反駁『光線只是差不多平行』的模糊觀念：幾何學是具有絕對確定性的理性科學。只要兩塊鏡面的平行度誤差在公差範圍內，光線的平行性就具備數學定理級別的嚴格保障，絕非經驗巧合。"
    },
