    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：l_1 \\parallel l_2 \\iff \\angle 1 = \\angle 2 \\text{ (內錯角)}, \\quad \\theta_{\\text{入}} = \\theta_{\\text{反}} = 45^\\circ \\implies \\Sigma = 180^\\circ$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
