    "text_scrutiny": "澳門市政署世遺核心區議事亭前地黑白波浪紋葡式碎石路（Calçada Portuguesa）測繪項目。\n工程師在電腦中設計圖案時指出：『這片覆蓋數千平方米的美麗波浪圖案，本質上是由一個最小的“基礎幾何元（黑白相間的小波浪模塊）”，沿著方向向量 T1(Δx1, Δy1) 與 T2(Δx2, Δy2) 不斷重複【剛體平移】鋪滿整個平面的！』\n初一電腦動畫小組提問：『在平移過程中，圖形的形狀、大小、周長、面積到底有沒有改變？連接各對應點的線段具備什麼驚人的幾何特性？』",
    "misconception": "學生容易把『平移』與『旋轉』、『翻折（對稱）』或『縮放』混淆，誤以為只要移動了就是平移，不理解平移的本質是『方向不變、所有點移動的距離絕對相等』的剛體變換。",
