      "evidence": "幾何測繪證明：原圖案多邊形頂點為 A, B, C，平移向量為 v = (50cm, 30cm)。平移後頂點為 A', B', C'。測得 AA' // BB' // CC'，且 |AA'| = |BB'| = |CC'| = √(50² + 30²) ≈ 58.3 cm。∠A = ∠A', S_ABC = S_A'B'C'。",
      "reasoning": "平移是仿射幾何中的保距同構變換。平面上任意一點 P(x, y) 映射為 P'(x + Δx, y + Δy)。由於變換矩陣的行列式為 1，幾何拓撲特徵完全守恆。若平移向量發生方向漂移（引入旋轉分量），對應線段將失去平行性，導致周期性密鋪條件被破壞，地面出現不可彌合的裂縫。",
