    "cps_challenge": "【多邊形頂點平移演算法】給定多邊形頂點坐標列表 vertices = [[0,0], [2,3], [4,0]] 與平移向量 [dx, dy]，用列表推導式編寫一行 Python 代碼生成平移後的頂點坐標集。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：(x', y') = (x + \\Delta x, \\, y + \\Delta y), \\quad |P'Q'| = \\sqrt{(x'_2 - x'_1)^2 + (y'_2 - y'_1)^2} = |PQ|$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
