    "text_scrutiny": "人教版 2024 七下《實數》附錄【閱讀與思考：為什麼 √2 不是有理數】。\n公元前 5 世紀古希臘畢達哥拉斯學派信奉『萬物皆數（整數及整數之比）』。學者希帕索斯畫出一個邊長為 1 的正方形，根據勾股定理，其對角線長度的平方等於 2（x² = 2，即 x = √2）。\n希帕索斯試圖找出兩個互質整數 p 和 q，使得 (p/q)² = 2，結果震驚地發現這在邏輯上根本不可能！學派為維護信條將其扔進地中海淹死，引發了人類歷史上『第一次數學危機』。請你用反證法重演這場震動人類文明的純邏輯論證。",
    "misconception": "學生以為世界上所有的數都可以寫成分數或有限小數，無法理解『無限不循環小數（無理數）』的本質，對『反證法（假設結論的反面成立，推導出與已知公理矛盾）』的高階邏輯證明方法缺乏訓練。",
    "cer": {
      "claim": "√2 絕對不可能表示為任何兩個整數的比值（即 √2 絕對不是有理數），無理數是客觀存在的嶄新數系維度。",
      "evidence": "反證法推導鏈條：假設 √2 = p/q（p, q ∈ Z 且 gcd(p, q) = 1）。則 p² = 2q² ⟹ p 為偶數，記 p = 2m。代入得 4m² = 2q² ⟹ q² = 2m² ⟹ q 亦為偶數。此時 2 是 p 和 q 的公約數，與 gcd(p, q) = 1 構成不可調和的邏輯矛盾（Contradiction）。因此原假設必然破滅，√2 ∉ Q。",
      "reasoning": "反證法（Reductio ad absurdum）是演繹邏輯的最高利器。若一個命題的反面必然導致邏輯崩潰與公理衝突，則該命題本身就是絕對無可置疑的真理。√2 的發現打破了整數比統治的世界觀，迫使人類數學從有理數邁入包含全體實數的連續完備新時代。",
      "rebuttal": "反駁『只是除法沒除完，除到一萬位說不定就循環了』的民科猜想：反證法從代數奇偶性質上直接在根源處封死了任何有限或循環分數的可能性，無論算到多少億位，√2 都永遠不會出現周期性循環。"
    },
    "cps_challenge": "【√2 的連分數展開演算法】探索 √2 = 1 + 1/(2 + 1/(2 + 1/...)) 的無限迭代連分數展開，寫出循環計算漸進分數的遞歸代碼。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：\\sqrt{2} = \\frac{p}{q} \\implies 2q^2 = p^2 \\implies 2 \\mid p \\implies p = 2k \\implies q^2 = 2k^2 \\implies 2 \\mid q \\quad (\\text{矛盾})$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
