    "title": "藥品安全劑量與電梯超載邊界——不等號方向顛倒的嚴密數理證明",
    "domain": "變化與關係 (Change & Relationships)",
    "pisa_coords": "【內容範疇】變化與關係 (Change & Relationships) | 【情境】公共安全、工程規範與醫藥健康 | 【認知過程】不等式性質三（同乘負數方向顛倒）的論證 | 【前瞻要素】風險邊界、不等式性質",
    "text_scrutiny": "澳門高層大廈客梯安全規章與兒童感冒藥說明書審查：\n• 某品牌電梯最大額定載重量為 1000 kg，安全控制系統要求：全體乘客總質量 W < 1000 kg；\n• 兒童退燒藥說明書標註：單次安全劑量區間為每公斤體重 10 mg 至 15 mg，嚴禁超量服用以免引發肝腎衰竭！\n課本出示不等式核心性質三：『不等式兩邊乘（或除以）同一個負數，不等號的方向【必須改變】！例如 2 < 3，兩邊乘 -1 變成 -2 > -3』。\n初一學生強烈質疑：『為什麼加減正負都不變號，乘除正數也不變號，偏偏乘除負數就要把不等號倒過來？憑什麼？！』",
    "misconception": "學生在解一元一次不等式時，遇到係數為負數（如 -2x < 6 ➔ 忘記變號寫成 x < -3），失分率高達 70%；對『同乘負數在數軸上相當於以原點為中心旋轉 180°、大小順序徹底顛倒』的空間幾何本質缺乏直觀深刻的認知。",
    "cer": {
      "claim": "不等式兩邊同乘（或除以）同一個負數時，不等號方向必須無條件顛倒；這是數軸空間對稱翻轉與代數移項性質的必然因果律。",
      "evidence": "1. 數軸幾何驗證：數軸上數的大小規則為『右邊的數大於左邊的數』。給任意 a < b 乘以 -1，點對稱映射到負半軸，原本距離原點更遠的 b 變成更靠左的 -b，故 -a > -b。\n2. 代數移項推導：已知 a < b。根據不等式性質一，兩邊同時減去 (a + b)：a - (a + b) < b - (a + b) ⟹ -b < -a，即 -a > -b。同理除以負數等價於乘以其倒數，結論完全成立。",
      "reasoning": "乘除負數在幾何本質上是『定向向量的方向反轉（Reflection across Origin）』。數軸是一維有向度量空間，負號反轉了空間坐標軸的箭頭朝向。順序關係在坐標系鏡像反轉下必然發生全序關係的倒置。若不改變不等號方向，將直接違背實數有序性公理。",
      "rebuttal": "反駁『公式太死板老記不住』的抱怨：變號不是死記口訣，而是客觀幾何位置的翻轉。記不住是因為只看符號不看數軸。想像一下鏡子裡的左右顛倒，乘負號就是數學世界的鏡像翻轉。"
    },
    "cps_challenge": "【不等式求解防忘變號演算法】編寫解不等式 ax < b 的程序模組：IF a > 0 THEN return x < b/a; ELSE IF a < 0 THEN return x > b/a; ELSE 報錯無解或全體實數。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：a < b \\land c < 0 \\implies ac > bc \\quad (\\because b - a > 0 \\implies (b - a) \\cdot (-c) > 0 \\implies ac > bc)$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
    "exp_name": "藥品安全劑量與電梯超載邊界 動態模擬實驗台",
    "exp_principle": "乘除負數在幾何本質上是『定向向量的方向反轉（Reflection across Origin）』。數軸是一維有向度量空間，負號反轉了空間坐標軸的箭頭朝向。順序關係在坐標系鏡像反轉下必然發生全序關係的倒置。若不改變不等號方向，將直接違背實數有序性公理。",
