    "unit": "第十二章 10.1 統計調查與抽樣設計",
    "title": "民調翻車慘案與抽樣偏差審查——MAIL 媒體素養與統計代表性批判",
    "domain": "不確定性與數據 (Uncertainty & Data)",
    "pisa_coords": "【內容範疇】不確定性與數據 (Uncertainty & Data) | 【情境】社會科學與公共民意調查 | 【認知過程】抽樣調查代表性批判與選擇性偏差審查 | 【前瞻要素】MAIL 數據素養、抽樣偏差",
    "text_scrutiny": "統計學歷史上最著名的世紀大翻車慘案——1936 年美國總統大選：\n權威雜誌《文學文摘》（Literary Digest）開展了史上規模最大的民意調查，採集發放了高達【1000 萬份問卷】，回收了驚人的【240 萬份有效問卷】！\n調查結果斬釘截鐵預測：共和黨候選人蘭登將以 57% 對 43% 的壓倒性優勢狂勝羅斯福！\n與此同時，剛剛創立的蓋洛普（Gallup）民調機構僅僅隨機抽樣了【5,000 人】，卻預測羅斯福將大獲全勝。\n大選結果公佈：羅斯福以 62% 得票率取得歷史性狂勝！《文學文摘》信用破產倒閉。初一數據審查小組提問：『240 萬人的大數據為什麼會輸給 5000 人的小樣本？樣本越大真的越準嗎？』",
    "misconception": "學生普遍存在『樣本數量越大越好、數據越多越可靠』的幼稚大數據迷信，完全忽略了『樣本代表性（Representativeness）』與『抽樣偏差（Sampling Bias）』對統計結論的毀滅性破壞。",
    "cer": {
      "claim": "樣本容量大絕不等於統計精確度高；《文學文摘》由於抽樣框存在嚴重的階級選擇性偏差，其 240 萬問卷得出的結論在統計學上完全無效。",
      "evidence": "1936 年美國大蕭條時期，只有高收入群體擁有電話和汽車。雜誌抽樣總體（電話簿與車主名冊）與全美選民總體存在巨大系統性偏差。蓋洛普僅用 n = 5,000 的科學分層隨機抽樣（涵蓋各階層真實比例），誤差控制在 3% 以內，精確命中大選結果。",
      "reasoning": "統計推斷的核心命脈在於『樣本的代表性與無偏性』。如果抽樣機制本身存在系統性偏差（Systematic Bias），那麼樣本容量越大，只是在以更高的確定性重複嚴重的系統錯誤！這如同用一把刻度本身短了 2cm 的尺子，量 1 億次也量不出物體的真實長度。",
      "rebuttal": "反駁『240 萬人比 5000 人多 480 倍肯定更準』的直覺：把湯攪勻了，喝一小勺（5000人）就能知道整鍋湯的味道；如果不攪勻只喝浮在上面的油花（富人電話本），喝一整碗（240萬人）也是滿嘴油，代表不了整鍋湯。代表性永遠高於樣本量。"
    },
    "cps_challenge": "【分層抽樣模擬演算法】編寫一個分層抽樣程序 stratified_sampling(population_dict, sample_size)，按各群體比例精確生成隨機抽樣名單。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：\\text{MoE} \\approx \\frac{1}{\\sqrt{n}}, \\quad \\text{Bias} = E(\\hat{p}) - p_{\\text{true}} \\neq 0 \\quad (\\text{抽樣框覆蓋率不足})$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
    "exp_name": "民調翻車慘案與抽樣偏差審查 動態模擬實驗台",
