    "title": "校服批量定做與正態分佈直覺——直方圖面積、組距與大數據分佈規律",
    "domain": "不確定性與數據 (Uncertainty & Data)",
    "pisa_coords": "【內容範疇】不確定性與數據 (Uncertainty & Data) | 【情境】學校後勤管理與工業服裝製造 | 【認知過程】頻數分佈表繪製、直方圖面積解碼與正態分佈直覺 | 【前瞻要素】數據可視化、鐘形曲線",
    "text_scrutiny": "聖若瑟教區中學第五校初一年級新學校服批量定做招標項目：\n學校採集了初一年級全體 200 名男生的精確身高數據（最小 142 cm，最大 178 cm，極差 36 cm）。\n校服廠製版師傅憑經驗建議：『把 140 到 180 cm 平均分成 S、M、L、XL 四個號碼，每個號碼各做 50 套！均勻生產最穩妥！』\n開學發放校服當天爆發嚴重危機：M 號和 L 號被搶購一空，幾十名同學沒有衣服穿；而 S 號和 XL 號在庫房堆積如山，嚴重滯銷！請你繪製頻數分佈直方圖，為校服廠揭示自然界身高的『鐘形對稱分佈秘密』。",
    "misconception": "學生直觀以為自然數據的分佈是『均勻分佈（每個區間人數一樣多）』，無法理解人類身高、考試成績等自然群體數據普遍服從『兩頭小、中間大、左右對稱』的高斯正態分佈規律；不知道頻數直方圖中『矩形面積代表頻數』的本質。",
    "cer": {
      "claim": "服裝師傅的均分方案違背了生物統計學正態分佈規律；校服採購必須依照頻數直方圖的分佈比例生產，中間碼（M/L）應佔總量 75%，極端碼（S/XL）僅需配比 10%。",
      "evidence": "200 名學生身高頻數統計：M 號對應區間 [150, 160) cm 共有 40 + 65 = 105 人（佔 52.5%）；L 號 [160, 170) cm 共有 45 + 20 = 65 人（佔 32.5%）。中等身材合計達 170 人（85%）。特小號 [140, 150) 僅 20 人（10%），特大號 [170, 180) 僅 10 人（5%）。均勻生產 50 套導致中間碼缺貨 70 套，兩頭碼滯銷 70 套。",
      "reasoning": "人類生理特徵（身高、體重、血壓）由大量微小獨立遺傳與環境因子共同決定，依據中心極限定理（CLT），其總體分佈嚴格服從高斯正態分佈。數據呈現『中間密集、兩側平緩衰減、單峰對稱』的鐘形特徵。直方圖矩形高度精確反映了概率密度。無視分佈特徵的平均主義是商業決策的災難。",
      "rebuttal": "反駁師傅『每個號碼都有人穿所以各做50套』的粗放思維：有需求不代表需求量相等。將非均勻的自然規律強行套用均勻模型，必然造成嚴重的庫存沉沒成本與供需失衡。"
    },
