    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：\\text{總面積} = \\sum_{i=1}^{k} \\left( \\Delta x_i \\times \\frac{\\text{頻數}_i}{\\Delta x_i} \\right) = \\sum_{i=1}^{k} \\text{頻數}_i = N_{\\text{總數}}$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
    "exp_name": "校服批量定做與正態分佈直覺 動態模擬實驗台",
