    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：C_{\\text{混合}} = \\frac{Q_{\\text{淡}} C_{\\text{淡}} + Q_{\\text{鹹}} C_{\\text{鹹}}}{Q_{\\text{淡}} + Q_{\\text{鹹}}} \\le 250\\text{ mg/L} \\implies Q_{\\text{淡}} \\ge Q_{\\text{鹹}} \\frac{C_{\\text{鹹}} - 250}{250 - C_{\\text{淡}}}$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
