    "cps_challenge": "【城市交通擁堵指數動態評價演算法】設計綜合擁堵指數公式：Congestion_Index = w1·(v_free/v_actual) + w2·(waiting_time/standard) + w3·(queue_length)，並編寫代碼實現多權重動態評分。",
    "cps_solution": "<strong>【代數模型與標準算法解析】</strong><br>依據本課數學模型，設核心變數為 $x$。列出方程或不等式進行求解：<br>$$\\text{模型公式}：\\text{TCI} = w_1 \\frac{v_{\\text{free}} - v}{v_{\\text{free}}} + w_2 \\frac{L_{\\text{queue}}}{L_{\\max}} + w_3 \\frac{T_{\\text{wait}}}{T_{\\max}} \\le 0.40 \\quad (\\sum w_i = 1)$$<br>分步驗算結果符合現實邊界約束，具備嚴密的學理邏輯。",
